using UnityEngine;
using System;
using System.IO;
using System.Collections.Generic;
using System.Globalization;

public class DemoApp:MonoBehaviour {
 [Serializable]public class Layout{public Vector3[] positions;}
 Transform[] artworks=new Transform[4];string status="WASD move, hold RMB look, E inspect",path="",imagePath="";Camera cam;
 void Start(){DemoWorld.Light();DemoWorld.Box("Floor",new Vector3(0,-.2f,0),new Vector3(16,.2f,20),Color.gray);DemoWorld.Box("Back wall",new Vector3(0,3,10),new Vector3(16,6,.2f),Color.white);for(int i=0;i<4;i++)artworks[i]=DemoWorld.Box("Artwork "+(i+1),new Vector3(-6+i*4,2.5f,9.7f),new Vector3(2.5f,2,.1f),Color.HSVToRGB(i*.22f,.65f,.9f)).transform;cam=DemoWorld.Camera(new Vector3(0,1.7f,-5));var rig=new GameObject("VisitorRig");cam.transform.SetParent(rig.transform,true);var n=rig.AddComponent<DemoNavigator>();n.view=cam;n.interact=g=>status="Selected: "+g.name;}
 // Geometry-only OBJ import. UV/materials/textures are intentionally not read.
 void ImportObj(){try{var lines=File.ReadAllLines(path);var vertices=new List<Vector3>();var triangles=new List<int>();foreach(var line in lines){var p=line.Split((char[])null,StringSplitOptions.RemoveEmptyEntries);if(p.Length==0)continue;if(p[0]=="v"&&p.Length>=4)vertices.Add(new Vector3(float.Parse(p[1],CultureInfo.InvariantCulture),float.Parse(p[2],CultureInfo.InvariantCulture),float.Parse(p[3],CultureInfo.InvariantCulture)));if(p[0]=="f"&&p.Length>=4){var ids=new List<int>();for(int i=1;i<p.Length;i++){int v=int.Parse(p[i].Split('/')[0]);v=v<0?vertices.Count+v:v-1;if(v<0||v>=vertices.Count)throw new Exception("Invalid OBJ index");ids.Add(v);}for(int i=1;i<ids.Count-1;i++){triangles.Add(ids[0]);triangles.Add(ids[i]);triangles.Add(ids[i+1]);}}}if(vertices.Count==0||triangles.Count==0)throw new Exception("No geometry");var mesh=new Mesh();mesh.indexFormat=UnityEngine.Rendering.IndexFormat.UInt32;mesh.SetVertices(vertices);mesh.SetTriangles(triangles,0);mesh.RecalculateNormals();var g=new GameObject("Imported scanned space");g.AddComponent<MeshFilter>().sharedMesh=mesh;var r=g.AddComponent<MeshRenderer>();r.material=new Material(Shader.Find("Standard")){color=Color.gray};status="Imported OBJ geometry (assumes meters). Use editor for textured FBX/OBJ.";}catch(Exception e){status=e.Message;}}
 void OnGUI(){GUILayout.BeginArea(new Rect(10,10,480,390),GUI.skin.box);GUILayout.Label("SPATIAL GALLERY | desktop + optional XR");GUILayout.Label(status);GUILayout.Label("OBJ absolute file path (geometry only):");path=GUILayout.TextField(path);if(GUILayout.Button("Import scanned OBJ"))ImportObj();GUILayout.Label("PNG/JPG absolute file path for first artwork:");imagePath=GUILayout.TextField(imagePath);if(GUILayout.Button("Load artwork image")){try{var tex=new Texture2D(2,2);if(!ImageConversion.LoadImage(tex,File.ReadAllBytes(imagePath)))throw new Exception("Invalid image");artworks[0].GetComponent<Renderer>().material.mainTexture=tex;status="Image loaded";}catch(Exception e){status=e.Message;}}if(GUILayout.Button("Move first artwork right"))artworks[0].position+=Vector3.right*.25f;if(GUILayout.Button("Save layout")){var l=new Layout{positions=new Vector3[artworks.Length]};for(int i=0;i<artworks.Length;i++)l.positions[i]=artworks[i].position;DemoWorld.Save("gallery.json",JsonUtility.ToJson(l));status="Saved";}if(GUILayout.Button("Load layout")){try{var s=DemoWorld.Load("gallery.json");if(s!=null){var l=JsonUtility.FromJson<Layout>(s);if(l.positions==null||l.positions.Length!=artworks.Length)throw new Exception("Invalid layout");for(int i=0;i<artworks.Length;i++)artworks[i].position=l.positions[i];status="Loaded";}}catch(Exception e){status=e.Message;}}GUILayout.EndArea();}
}
